"""Evaluation helpers. Labels are consumed only after scores exist (R9, R10)."""
import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score


def roc_auc(scores, y):
    return float(roc_auc_score(np.asarray(y).ravel(), np.asarray(scores).ravel()))


def auc_pr(scores, y):
    """Primary AUC-PR: sklearn average_precision_score (ADBench convention)."""
    return float(average_precision_score(np.asarray(y).ravel(), np.asarray(scores).ravel()))


def auc_pr_trapz(scores, y):
    """Secondary AUC-PR: trapezoidal area under the precision-recall curve."""
    p, r, _ = precision_recall_curve(np.asarray(y).ravel(), np.asarray(scores).ravel())
    trap = getattr(np, "trapezoid", None) or np.trapz
    return float(trap(p, r))


def summarize(values):
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
    }

